CREATE TABLE IF NOT EXISTS course_projects (
  id TEXT PRIMARY KEY,
  course_id TEXT NOT NULL,
  module_id TEXT,
  lesson_id TEXT,
  title TEXT NOT NULL,
  description TEXT NOT NULL,
  brief TEXT,
  requirements TEXT DEFAULT '[]',
  tools TEXT DEFAULT '[]',
  steps TEXT DEFAULT '[]',
  gigo_prompt TEXT,
  required_languages TEXT DEFAULT '[]',
  min_commits INTEGER DEFAULT 1,
  requires_readme INTEGER DEFAULT 1,
  requires_demo INTEGER DEFAULT 0,
  order_index INTEGER DEFAULT 0,
  created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE
);
ALTER TABLE projects ADD COLUMN project_id TEXT;
ALTER TABLE projects ADD COLUMN notes TEXT;
ALTER TABLE projects ADD COLUMN repo_verified INTEGER DEFAULT 0;
ALTER TABLE projects ADD COLUMN verification TEXT DEFAULT '{}';
ALTER TABLE projects ADD COLUMN verified_at TEXT;
ALTER TABLE projects ADD COLUMN last_commit_at TEXT;
CREATE INDEX IF NOT EXISTS idx_course_projects_course ON course_projects(course_id, order_index);
CREATE INDEX IF NOT EXISTS idx_projects_user_project ON projects(user_id, project_id);
INSERT INTO course_projects (id,course_id,title,description,brief,requirements,tools,steps,gigo_prompt,required_languages,min_commits,requires_readme,requires_demo,order_index)
VALUES ('b7754a4f-a57a-4210-955b-e016161720d9','75383252-a640-4828-81ca-ac8546e43207','Capstone Project: Artificial Intelligence','Apply Artificial Intelligence in a real, verifiable project. Submit a public GitHub repository and pass the repository checks.','Build a portfolio-ready project that proves you can apply Artificial Intelligence without following a tutorial line by line.

This is not a quiz. You will plan the work, build it in small commits, document your decisions, and submit a public GitHub repository. The CareerCode verifier checks that the repository exists, is public, has real commits, has a README and uses the expected language. GiGo can review your plan, a screenshot of an error, or a screen recording of your debugging session.

Project focus: A clear problem statement and dataset, A baseline before the advanced model, Training/evaluation code that can be reproduced.','["A clear problem statement and dataset", "A baseline before the advanced model", "Training/evaluation code that can be reproduced", "Metrics appropriate to the task", "A short demo or notebook walkthrough", "A README with limitations and ethical notes"]','["Python", "PyTorch or scikit-learn", "Hugging Face", "GitHub", "Jupyter"]','["Define the task and success metric.", "Build a baseline.", "Train or prompt the model.", "Evaluate with a held-out set.", "Document failure cases.", "Create a short demo.", "Ask GiGo to review your evaluation plan."]','I am working on the capstone project for "Artificial Intelligence" on CareerCode.
Help me plan it, not copy it. Ask me for my one-page brief, then give me:
1. a milestone plan with 5-7 small commits,
2. the tools and setup commands I need,
3. the acceptance criteria I should test,
4. the first file or command to create.
If I upload a screenshot, inspect the actual error and tell me what to fix.','["Python", "Jupyter Notebook"]',3,1,1,0);
